import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

/**
 * Paths to the test fixtures. The fixtures are generated by
 * `scripts/make-fixtures.ts` (WS1, see the fixtures table in the plan):
 * small ones are committed in tests/fixtures/, large ones are generated in
 * Playwright globalSetup into tests/fixtures/.gen/.
 */

const here = dirname(fileURLToPath(import.meta.url));
export const FIXTURES_DIR = resolve(here, '..', 'fixtures');
export const GEN_DIR = resolve(FIXTURES_DIR, '.gen');

export type FixtureName =
  | 'text-3p.pdf'
  | 'text-10p.pdf'
  | 'mixed-sizes.pdf'
  | 'headings.pdf'
  | 'with-image.pdf'
  | 'secret.pdf'
  | 'scanned.pdf'
  | 'scanned-hi.pdf'
  | 'encrypted.pdf'
  | 'form.pdf'
  | 'photo-portrait-exif6.jpg'
  | 'photo-1.jpg'
  | 'photo-2.png'
  | 'photo-3.webp'
  | '.gen/large-200p.pdf'
  | '.gen/photos-hi-res.pdf';

export function fixturePath(name: FixtureName): string {
  return resolve(FIXTURES_DIR, name);
}

export function readFixture(name: FixtureName): Uint8Array {
  const p = fixturePath(name);
  if (!existsSync(p)) {
    throw new Error(
      `fixture ${name} is missing at ${p}: run \`npm run fixtures\` (scripts/make-fixtures.ts, WS1)`,
    );
  }
  return new Uint8Array(readFileSync(p));
}
